_FLAT_WARPS_SMALL = 4
_FLAT_BLOCK_MID = 1024
_FLAT_WARPS_MID = 4
_FLAT_BLOCK_MID_BF16 = 2048
_FLAT_WARPS_MID_BF16 = 4
_FLAT_SMALL_LIMIT = 1 << 20
_FLAT_MID_LIMIT = 1 << 25
_STRIDED_BLOCK = 1024
_STRIDED_WARPS = 4
_ALIGN_BYTES = 16
