_OUT_FP16_VIA32 = 1  # float32 round first (native float64 -> float16 path)
_OUT_FP32 = 2
_OUT_FP64 = 3
_OUT_BF16 = 4

# Backward converts the float16 gradient back to the input dtype.
_BACKWARD_MODE = {
    torch.float32: _OUT_FP32,
    torch.float64: _OUT_FP64,
    torch.bfloat16: _OUT_BF16,
    torch.complex64: _OUT_FP32,
    torch.complex128: _OUT_FP64,
}
_MODE_DTYPE = {
    _OUT_FP32: torch.float32,
    _OUT_FP64: torch.float64,
    _OUT_BF16: torch.bfloat16,
}


