            source_ptr,
            out,
            n,
            OUT_MODE=out_mode,
            WIDE=n >= _INT32_LIMIT,
            ALIGNED=aligned,
            COMPLEX_INPUT=complex_input,
            BLOCK=block,
            num_warps=warps,
