            source_ptr,
            out,
            n,
            SHAPE=tuple(source.shape),
            SRC_STRIDES=tuple(source.stride()),
            DST_STRIDES=tuple(out.stride()),
            OUT_MODE=out_mode,
            COMPLEX_INPUT=complex_input,
            BLOCK=_STRIDED_BLOCK,
            num_warps=_STRIDED_WARPS,
